  async commit(name:string,msg:string){if(!msg.trim())throw new LabError('EMPTY_MESSAGE','Mensagem de commit vazia.');return this.mutate('commit-layer',async()=>{const l=this.layer(name,true);const {staged}=await this.changes(l);if(!staged.length)throw new LabError('NOTHING_STAGED','Nenhuma alteração preparada.');await git(this.repo.root,['var','GIT_AUTHOR_IDENT']);await git(this.repo.root,['var','GIT_COMMITTER_IDENT']);const tree=await this.checkpoint(l);await this.owners();const oid=await gitText(this.repo.root,['commit-tree',tree,'-p',l.oid,'-F','-'],{input:msg+'\n'});this.tx!.data.recovery.commit={ref:l.ref,old:l.oid,new:oid,layerId:l.id};await this.tx!.record('commit-prepared',{oid});await git(this.repo.root,['update-ref',l.ref,oid,l.oid]);await this.tx!.record('commit-ref-updated',{oid});failpoint('after-commit-ref');l.oid=oid;l.indexBase=oid;const newPaths=new Set((await treeEntries(this.repo.root,oid)).map(e=>e.path));l.reservations=l.reservations.filter(p=>!newPaths.has(p));await this.updateExcludes();return {oid,ref:l.ref,tree};});}
